function admin_nav(string $href,string $label,string $icon,array $matches=[]): string {
    $page=basename((string)($_SERVER['SCRIPT_NAME']??''));
    $active=in_array($page,array_merge([$href],$matches),true);
    return '<a class="admin-nav-link'.($active?' active':'').'" href="'.$href.'"><span class="admin-nav-icon">'.admin_icon($icon).'</span><span>'.$label.'</span></a>';
}

function admin_notice(string $message,string $type='success'): void {
    $type=$type==='error'?'error':'success';
    echo '<div class="admin-notice '.$type.'" role="status">'.aesc($message).'</div>';
}

