a-label="Светлая тема"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"></circle><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.42-1.41M17.66 6.34l1.41-1.41"></path></svg></button><button class="admin-theme-button" type="button" data-theme-value="dark" title="Тёмная тема" aria-label="Тёмная тема"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg></button></div><div class="admin-theme-label">Размер текста</div><div class="admin-font-switch" role="group" aria-label="Размер текста"><button class="admin-font-button" type="button" data-font-size-value="small" title="Мелкий текст" aria-label="Мелкий текст">A</button><button class="admin-font-button" type="button" data-font-size-value="normal" title="Обычный текст" aria-label="Обычный текст">A</button><button class="admin-font-button" type="button" data-font-size-value="large" title="Крупный текст" aria-label="Крупный текст">A</button></div><a class="admin-nav-link admin-logout" href="logout.php"><span class="admin-nav-icon"><?=admin_icon('logout')?></span><span>Выход из системы</span></a></div></aside><main class="admin-main"><div class="admin-topbar"><div class="admin-breadcrumb"><strong><?=aesc($title)?></strong></div><div class="admin-user"><span class="admin-user-avatar">А</span><span>Администратор</span></div></div><div class="admin-content"><div class="admin-page-head"><div><h1><?=aesc($title)?></h1></div></div><?php }
function admin_footer(): void { ?></div></main></div><script>(function(){var themeButtons=[].slice.call(document.querySelectorAll('[data-theme-value]'));var fontButtons=[].slice.call(document.querySelectorAll('[data-font-size-value]'));function applyTheme(theme){theme=theme==='light'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('ciritas_theme',theme)}catch(e){}themeButtons.forEach(function(b){var active=b.dataset.themeValue===theme;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active?'true':'false')})}function applyFont(size){size=(size==='small'||size==='large')?size:'normal';document.documentElement.dataset.fontSize=size;try{localStorage.setItem('ciritas_admin_font_size',size)}catch(e){}fontButtons.forEach(function(b){var active=b.dataset.fontSizeValue===size;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active?'true':'false')})}applyTheme(document.documentElement.dataset.theme||'dark');applyFont(document.documentElement.dataset.fontSize||'normal');themeButtons.forEach(function(b){b.addEventListener('click',function(){applyTheme(b.dataset.themeValue)})});fontButtons.forEach(function(b){b.addEventListener('click',function(){applyFont(b.dataset.fontSizeValue)})})})();</script></body></html><?php }
